class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.build_tree(arr, 1, 0, self.n - 1)

    def build_tree(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            self.build_tree(arr, 2 * node, start, mid)
            self.build_tree(arr, 2 * node + 1, mid + 1, end)
            self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, node, start, end, q_start, q_end):
        if q_start <= start and end <= q_end:
            return self.tree[node]
        if end < q_start or start > q_end:
            return float('-inf')
        mid = (start + end) // 2
        return max(self.query(2 * node, start, mid, q_start, q_end),
                   self.query(2 * node + 1, mid + 1, end, q_start, q_end))


def range_query(arr, query):
    start, end = query
    return [arr[i] for i in range(start, end + 1)]


# Example usage
